# bash completion for kombinat; generated by `kombinat completion bash`, do not edit.
_kombinat() {
  local cur=${COMP_WORDS[COMP_CWORD]} p="" w i words=""
  for ((i = 1; i < COMP_CWORD; i++)); do
    w=${COMP_WORDS[i]}
    [[ $w == -* ]] && continue
    p+="${p:+ }$w"
  done
  if [[ $cur == -* ]]; then
    case $p in
      "log") words="--tail --after" ;;
    esac
    words+=" --json --no-color --help"
  else
    case $p in
      "") words="completion config help log serve version" ;;
      "completion") words="bash zsh fish" ;;
      "config") words="show" ;;
      "help") words="completion config help log serve version" ;;
    esac
  fi
  mapfile -t COMPREPLY < <(compgen -W "$words" -- "$cur")
}
complete -F _kombinat kombinat
